/**
 * Sub-issue tree rules that need no database: the depth ceiling and the error
 * raised when a placement would loop or nest too deeply.
 *
 * The tree itself is walked in `@/server/services/issue-service`; this module
 * only states what a refused placement looks like.
 */
import { MAX_SUB_ISSUE_DEPTH } from "@/config/constants";

export class IssueHierarchyError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly issueId: string,
    readonly reason: "cycle" | "too_deep",
  ) {
    super(
      reason === "cycle"
        ? `Issue ${issueId} cannot be placed under itself or its own sub-issues.`
        : `Issue ${issueId} would sit deeper than ${MAX_SUB_ISSUE_DEPTH} levels.`,
    );
    this.name = "IssueHierarchyError";
  }
}

/** Throws when the deepest issue of a placement would land below the ceiling. */
export function assertDepthAllowed(issueId: string, deepestLevel: number): void {
  if (deepestLevel > MAX_SUB_ISSUE_DEPTH) {
    throw new IssueHierarchyError(issueId, "too_deep");
  }
}
EOF
